using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Guards the dependency rule (Infrastructure -> Application -> Domain) by inspecting the compiled
/// assemblies' metadata. Kept out of the unit-test project so the per-save suite stays fast.
/// </summary>
public class LayerDependencyTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Text.Json", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "System.Xml", "Microsoft.",
    ];

    private static readonly Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly InfrastructureAssembly = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_other_layers_or_technical_details()
    {
        var offenders = Violations(DomainAssembly, ApplicationAssembly.GetName().Name!, InfrastructureAssembly.GetName().Name!);
        Assert.Empty(offenders);
    }

    [Fact]
    public void Application_does_not_depend_on_Infrastructure_or_technical_details()
    {
        var offenders = Violations(ApplicationAssembly, InfrastructureAssembly.GetName().Name!);
        Assert.Empty(offenders);
    }

    private static List<string> Violations(Assembly assembly, params string[] forbiddenAssemblies)
    {
        var offenders = new List<string>();

        foreach (var reference in assembly.GetReferencedAssemblies())
            if (forbiddenAssemblies.Contains(reference.Name))
                offenders.Add($"{assembly.GetName().Name} references assembly {reference.Name}");

        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var metadata = pe.GetMetadataReader();
        foreach (var handle in metadata.TypeReferences)
        {
            var type = metadata.GetTypeReference(handle);
            var ns = metadata.GetString(type.Namespace);
            if (TechnicalNamespaces.Any(t => ns == t.TrimEnd('.') || ns.StartsWith(t.EndsWith('.') ? t : t + ".")))
                offenders.Add($"{assembly.GetName().Name} uses {ns}.{metadata.GetString(type.Name)}");
        }

        return offenders;
    }
}
